import java.util.Scanner;

public class CF_630_D2_E_Variant2 {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        int L = sc.nextInt();
        int R = sc.nextInt();

        long mod = 998244353;
        long inv2 = powerMod(2, mod - 2, mod);
        long diff = R - L + 1;
        long p1 = diff / 2;
        long p2 = diff - p1;
        long ans;

        if ((n * m) % 2 == 1) {
            ans = powerMod(diff, n * m, mod);
        } else {
            long pp1 = diff;
            long pp2 = Math.abs(p1 - p2);
            long opt1 = powerMod(pp1, n * m, mod);
            long opt2 = powerMod(pp2, n * m, mod);
            long opt = (opt1 + opt2) % mod;
            ans = (opt * inv2) % mod;
        }
        System.out.println(ans);
        sc.close();
    }

    static long powerMod(long base, long exp, long mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
